-- https://lua.expert

local v1, v2
local v3 = table.concat({
    script:WaitForChild("Data1").Value,
    script:WaitForChild("Data2").Value,
    script:WaitForChild("Data3").Value,
    script:WaitForChild("Data4").Value
})

return {
    Get = function() -- Get | line: 5
        -- upvalues: v1 (ref), v2 (ref), v3 (copy)
        if v2 then
            return v2
        end

        v1 = game:GetService("AssetService"):CreateEditableImage({
            Size = Vector2.new(534, 330)
        })
        assert(v1, "Unable to allocate bike artwork")

        local v5 = buffer.create(704880)
        local t2 = {}

        for i = 1, 64 do
            t2[("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"):byte(i)] = i - 1
        end

        local t3 = {}

        for i = 1, 1752, 8 do
            local v7 = tonumber((""):sub(i, i + 1), 16)
            local v9 = tonumber((""):sub(i + 2, i + 3), 16)
            local v11 = tonumber((""):sub(i + 4, i + 5), 16)
            local v13 = tonumber((""):sub(i + 6, i + 7), 16)

            table.insert(t3, v7 + v9 * 256 + v11 * 65536 + v13 * 16777216)
        end

        local n1 = 0

        for i = 1, #v3, 3 do
            local v16 = t3[t2[v3:byte(i)] * 64 + t2[v3:byte(i + 1)] + 1]

            for _ = 1, t2[v3:byte(i + 2)] + 1 do
                buffer.writeu32(v5, n1, v16)
                n1 += 4
            end

            if i % 12288 == 1 then
                task.wait()
            end
        end

        assert(n1 == 704880, "Artwork pixel count mismatch")
        v1:WritePixelsBuffer(Vector2.zero, Vector2.new(534, 330), v5)
        v2 = Content.fromObject(v1)

        return v2
    end
}
